mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM remediation_approvals a
    WHERE a.incident_code = #{incidentCode}
      AND a.plan_id IS NOT NULL
      AND a.decision IN ('PENDING', 'APPROVED')
      AND NOT EXISTS (
          SELECT 1 FROM remediation_executions e WHERE e.approval_id = a.approval_id
      )
)
